template.solver:
def solve(L, U):
    K = list(range(L + 1, U))
    M = 1
    for i in range(1, U):
        M = lcm(M, i)
    N = 2 * M + 2 * U * U
    best = 0
    for n in range(1, N):
        c = 0
        for k in K:
            t = n - k * (k - 1) // 2
            if t >= k and t % k == 0:
                c += 1
        if c > best:
            best = c
    return best
